import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { Activity, ArrowDownRight, ArrowUpRight, BarChart3, Check, ChevronRight, CircleDollarSign, Clock3, CreditCard, Download, Eye, FileText, Gift, ImagePlus, Package, Pencil, Plus, Search, ShoppingBag, SlidersHorizontal, Sparkles, Tag, Trash2, TrendingUp, Truck, Users, Wallet } from "lucide-react";
import { useAdmin } from "@/store/admin";
import { getCategories } from "@/lib/catalog";
import { DEFAULT_SETTINGS } from "@/store/admin";
import { KEYS } from "@/lib/storage";
import { AdminLogin, DataTable, DeleteDialog, EmptyState, FamilyBadge, formatMoney, ImageUpload, PageHeader, ProductEditor, SectionTabs, ShowcaseEditor, StatCard, StatusBadge } from "@/components/admin/shared";
import { RuleEditor } from "@/components/admin/rule-editor";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
